xml.Script:
        clYellow       := 'FFFF00';
        clLightBlue    := '2828FF';
        clBlue         := '0000A0';
        clBrown        := '800000';
        clLightViolett := 'FF0080';
        clRed          := 'FF0000';
        clLightGreen   := '00FF00';
        clGreen        := '008000';
        clViolett      := '800080';
        clCyan         := '00DCB4';
        clWhite        := 'FFFFFF';
        clBlack        := '222222';
        clBrass        := 'B5A642';
        clBubbleGum    := 'FFC1CC';
        clDesert       := 'C19A6b';
        clEggplant     := '614051';
        clEmerald      := '50C878';

        for i := 0 to 4 do
            Colors[i] := -1;

        Colors[ 5] := clBubbleGum;
        Colors[ 6] := clEggplant;
        Colors[ 7] := clEmerald;
        Colors[ 8] := clDesert;
        Colors[ 9] := clBrass;
        Colors[10] := clWhite;
        Colors[11] := clBlue;
        Colors[12] := clLightBlue;
        Colors[13] := clLightGreen;
        Colors[14] := clGreen;
        Colors[15] := clRed;
        Colors[16] := clLightViolett;
        Colors[17] := clViolett;
        Colors[18] := clBrown;
        Colors[19] := clCyan;

        R := 0.7;
        include 'Figures\Scripts\Icosahedron_Coordinates.inc';

        jumAngle := Arcsin(1/4) + Pi/6;
